import { ClienteMock } from "@/app/mock/cliente";
import Link from "next/link";
import { useEffect, useState } from "react";
import { Cliente } from "@/app/context/AuthContext";

export default function Cliente() {

    const [clientes, setClientes] = useState<Cliente[]>([]);

    useEffect(() => {
        carregarDados();
    }, []);

    const carregarDados = async () => {
        try {
            const dados = await ClienteMock.listarTodos();
            setClientes(dados);
        } catch (error) {
            console.error(error)
        }
    }

    const handleAlterarStatus = async (cliente:Cliente)=>{
        try{
            setClientes( clientesAtuais => clientesAtuais.map(c=>c.codigo === cliente.codigo?new Cliente(c.codigo,c.nome,c.telefone,c.cpf,!c.ativo) : c))
        }catch(error){
            alert("Erro ao editar")
        }
    }

    return (
        <div className="max-w-4xl mx-auto p-6 md:p-10 font-sans transition-colors">
            {/* SEÇÃO 2: LISTA E BUSCA */}
            <div className="space-y-8">

                {/* Cabeçalho da Lista: Título e Botão */}
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6">
                    <div>
                        <h3 className="text-2xl font-black text-slate-900 dark:text-slate-50 tracking-tighter uppercase italic">
                            Lista de <span className="text-amber-500">clientes</span>
                        </h3>
                        <p className="text-xs text-slate-500 uppercase tracking-widest mt-1">Gerencie sua base de contatos</p>
                    </div>

                    <Link
                        href="/cliente/novo"
                        className="inline-flex items-center justify-center gap-2 px-6 py-3 bg-amber-500 hover:bg-amber-600 dark:bg-amber-500 dark:hover:bg-amber-400 text-[#2B344B] font-bold rounded-2xl transition-all shadow-lg shadow-amber-500/20 active:scale-95 group"
                    >
                        <svg
                            xmlns="http://www.w3.org/2000/svg"
                            width="18"
                            height="18"
                            viewBox="0 0 24 24"
                            fill="none"
                            stroke="currentColor"
                            strokeWidth="3"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                            className="transition-transform group-hover:rotate-90"
                        >
                            <line x1="12" y1="5" x2="12" y2="19"></line>
                            <line x1="5" y1="12" x2="19" y2="12"></line>
                        </svg>
                        <span className="text-[10px] uppercase tracking-[0.2em]">Novo Cliente</span>
                    </Link>
                </div>

                {/* Barra de Busca - Estilizada para combinar com o novo padrão */}
                <div className="relative group w-full">
                    <input
                        type="search"
                        placeholder="Buscar por nome ou telefone..."
                        className="w-full pl-14 pr-6 py-4 bg-white dark:bg-[#1F2636] border border-slate-200 dark:border-white/5 rounded-2xl focus:outline-none focus:border-amber-400 transition-all text-sm text-slate-800 dark:text-slate-100 shadow-xl shadow-black/5"
                    />
                    <div className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-amber-400 transition-colors">
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                            <circle cx="11" cy="11" r="8"></circle>
                            <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
                        </svg>
                    </div>
                </div>
                <div className="overflow-x-auto">
                    <table>
                        <thead>
                            <tr>
                                <th>Código</th>
                                <th>Nome</th>
                                <th>Telefone</th>
                                <th>CPF</th>
                            </tr>
                        </thead>
                        <tbody>
                            {clientes.map((cliente) =>

                                <tr key={cliente.codigo}>
                                    <td>{cliente.codigo}</td>
                                    <td>{cliente.nome}</td>
                                    <td>{cliente.telefone}</td>
                                    <td>{cliente.cpf}</td>
                                    <td>{cliente.ativo? 'Ativo' : 'Inativo'}</td>
                                    <td>Ações editar e ativar/inativar</td>
                                    <td>
                                        <Link href={`/cliente/${cliente.codigo}/editar`}>Editar</Link>
                                        <button onClick={()=>handleAlterarStatus(cliente)}>{cliente.ativo? 'Ativar' : 'Inativar'}</button>
                                    </td>
                                </tr>

                            )}
                            { clientes.length === 0 && (
                                <tr>
                                    <td>Nenhum cliente encontrado.</td>
                                </tr>
                            )
                            
                            }

                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}